import { DomainError, port, requireValue } from '../core/contracts.js';
import { verifySnapshot } from './backup-service.js';
import { stableStringify } from '../resilience/recovery-bundle.js';

export const methods = ['plan', 'verify', 'restore'];
export const RESTORE_PLAN_SCHEMA = 'MEL_RESTORE_PLAN_V1';

function asArray(value) {
  return Array.isArray(value) ? value : [];
}

function validateDatabaseExport(value) {
  if (!value || value.type !== 'MEL_D1_LOGICAL_EXPORT_V1') {
    return { ok: false, code: 'RESTORE_D1_EXPORT_REQUIRED' };
  }
  const tables = asArray(value.tables);
  if (Number(value.tableCount || 0) !== tables.length) {
    return { ok: false, code: 'RESTORE_D1_TABLE_COUNT_MISMATCH' };
  }
  for (const table of tables) {
    if (!table || !String(table.name || '').trim() || !Array.isArray(table.rows)) {
      return { ok: false, code: 'RESTORE_D1_TABLE_INVALID' };
    }
    if (Number(table.rowCount || 0) !== table.rows.length) {
      return { ok: false, code: 'RESTORE_D1_ROW_COUNT_MISMATCH', table: table.name || null };
    }
  }
  return {
    ok: true,
    tableCount: tables.length,
    rowCount: tables.reduce((sum, table) => sum + table.rows.length, 0),
  };
}

const PATRIMONY_TABLES = ['evolution_ledger', 'conversations', 'dev_jobs'];

function validatePatrimonyExport(value) {
  const validation = validateDatabaseExport(value);
  if (!validation.ok) return validation;
  const tables = new Map();
  for (const table of asArray(value.tables)) {
    const name = String(table.name);
    if (tables.has(name)) return { ok: false, code: 'RESTORE_PATRIMONY_DUPLICATE_TABLE', table: name };
    tables.set(name, table);
  }
  for (const name of PATRIMONY_TABLES) {
    const table = tables.get(name);
    if (!table) return { ok: false, code: 'RESTORE_PATRIMONY_TABLE_REQUIRED', table: name };
    if (typeof table.schema !== 'string' || !table.schema.trim()) {
      return { ok: false, code: 'RESTORE_PATRIMONY_SCHEMA_REQUIRED', table: name };
    }
    const idField = name === 'evolution_ledger' ? 'event_id' : 'id';
    const ids = new Set();
    for (const row of table.rows) {
      const id = row?.[idField];
      if (typeof id !== 'string' || !id.trim()) {
        return { ok: false, code: 'RESTORE_PATRIMONY_ROW_ID_REQUIRED', table: name };
      }
      if (ids.has(id)) return { ok: false, code: 'RESTORE_PATRIMONY_DUPLICATE_ROW_ID', table: name };
      ids.add(id);
    }
  }
  return { ok: true, tables };
}

/** Compare complete patrimony data and schema without depending on export order or writing production. */
export function comparePatrimonyExports(before, after) {
  const left = validatePatrimonyExport(before);
  if (!left.ok) return { ...left, identical: false, side: 'before', production_written: false };
  const right = validatePatrimonyExport(after);
  if (!right.ok) return { ...right, identical: false, side: 'after', production_written: false };
  const tables = {};
  let identical = true;
  for (const name of PATRIMONY_TABLES) {
    const previousTable = left.tables.get(name);
    const nextTable = right.tables.get(name);
    const previous = previousTable.rows;
    const next = nextTable.rows;
    const same = previousTable.schema === nextTable.schema
      && previous.length === next.length
      && stableStringify(previous.map(stableStringify).sort()) === stableStringify(next.map(stableStringify).sort());
    if (!same) identical = false;
    tables[name] = { before: previous.length, after: next.length, same };
  }
  return { ok: true, identical, tables, production_written: false };
}

async function tableFingerprint(table) {
  const canonical = stableStringify({ schema: table.schema, rows: table.rows.map(stableStringify).sort() });
  const digest = await crypto.subtle.digest('SHA-256', new TextEncoder().encode(canonical));
  return [...new Uint8Array(digest)].map(byte => byte.toString(16).padStart(2, '0')).join('');
}

/**
 * MEL-FOUNDER-07: restore a patrimony export into an isolated copy, then
 * compare row counts and per-table SHA-256 fingerprints. The target must
 * declare itself isolated before anything is written; production is refused.
 */
export async function verifyIsolatedRestore(exported, target) {
  if (!target || target.isolated !== true || target.production === true || typeof target.restore !== 'function') {
    return { ok: false, code: 'RESTORE_ISOLATED_TARGET_REQUIRED', identical: false, production_written: false };
  }
  const source = validatePatrimonyExport(exported);
  if (!source.ok) return { ...source, identical: false, side: 'before', production_written: false };
  const restored = await target.restore(structuredClone(exported));
  const comparison = comparePatrimonyExports(exported, restored);
  if (!comparison.ok) return comparison;
  const after = validatePatrimonyExport(restored);
  const fingerprints = {};
  for (const name of PATRIMONY_TABLES) {
    fingerprints[name] = { before: await tableFingerprint(source.tables.get(name)), after: await tableFingerprint(after.tables.get(name)) };
    comparison.tables[name].fingerprint_match = fingerprints[name].before === fingerprints[name].after;
  }
  return { ...comparison, fingerprints, isolated: true, production_written: false };
}

export function registerPatrimonyCompareCapability(bus) {
  if (!bus || typeof bus.discover !== 'function') throw new TypeError('CAPABILITY_BUS_REQUIRED');
  bus.discover({
    id: 'backup.patrimony.compare',
    name: 'Comparer deux exports du patrimoine',
    category: 'resilience',
    version: '1.0.0',
    provider: 'mel',
    description: 'Compares evolution_ledger, conversations and dev_jobs between two logical exports. It never writes production.',
    input_schema: {
      type: 'object',
      properties: {
        before: { type: 'object', additionalProperties: true },
        after: { type: 'object', additionalProperties: true },
      },
      required: ['before', 'after'],
      additionalProperties: false,
    },
    output_schema: { type: 'object', additionalProperties: true },
    risk: 'LOW',
    permissions: [],
    health: 'DEGRADED',
    enabled: true,
  }, async (input) => comparePatrimonyExports(input?.before, input?.after));
}

function validateR2Inventory(value) {
  if (!value || value.type !== 'MEL_R2_INVENTORY_V1') {
    return { ok: false, code: 'RESTORE_R2_INVENTORY_REQUIRED' };
  }
  const objects = asArray(value.objects);
  if (Number(value.objectCount || 0) !== objects.length) {
    return { ok: false, code: 'RESTORE_R2_OBJECT_COUNT_MISMATCH' };
  }
  for (const object of objects) {
    if (!object || !String(object.key || '').trim() || Number(object.size || 0) < 0) {
      return { ok: false, code: 'RESTORE_R2_OBJECT_INVALID' };
    }
  }
  return {
    ok: true,
    objectCount: objects.length,
    totalBytes: objects.reduce((sum, object) => sum + Number(object.size || 0), 0),
  };
}

function validateRuntimeDescriptor(value) {
  if (!value || value.type !== 'MEL_RUNTIME_DESCRIPTOR_V1') {
    return { ok: false, code: 'RESTORE_RUNTIME_DESCRIPTOR_REQUIRED' };
  }
  if (!String(value.appVersion || '').trim() || !String(value.worker || '').trim()) {
    return { ok: false, code: 'RESTORE_RUNTIME_DESCRIPTOR_INVALID' };
  }
  return {
    ok: true,
    appVersion: value.appVersion,
    dbSchemaVersion: value.dbSchemaVersion ?? null,
    candidateBranch: value.candidateBranch || null,
    deployedGitSha: /^[a-f0-9]{40}$/i.test(String(value.deployedGitSha || '')) ? String(value.deployedGitSha).toLowerCase() : null,
    deployedGitBranch: value.deployedGitBranch || null,
  };
}

export function inspectRestoreCandidate(snapshot, { integrity = null } = {}) {
  const exported = snapshot?.exports || {};
  const database = validateDatabaseExport(exported.database);
  if (!database.ok) return { ok: false, ...database, ...(integrity ? { integrity } : {}) };
  const r2 = validateR2Inventory(exported.r2_inventory);
  if (!r2.ok) return { ok: false, ...r2, ...(integrity ? { integrity } : {}) };
  const runtime = validateRuntimeDescriptor(exported.runtime);
  if (!runtime.ok) return { ok: false, ...runtime, ...(integrity ? { integrity } : {}) };

  return {
    ok: true,
    code: 'RESTORE_CANDIDATE_VERIFIED',
    snapshot_id: snapshot.id,
    integritySha256: snapshot.integritySha256,
    database,
    r2,
    runtime,
    ...(integrity ? { integrity } : {}),
    critical_recovery_scope: {
      d1_logical_state_reconstructable: true,
      r2_inventory_verified: true,
      r2_object_bytes_embedded: false,
      production_activation_automatic: false,
    },
  };
}

export async function verifyRestoreCandidate(snapshot) {
  const integrity = await verifySnapshot(snapshot);
  if (!integrity?.ok) return { ok: false, code: integrity?.code || 'RESTORE_SNAPSHOT_INVALID', integrity };
  return inspectRestoreCandidate(snapshot, { integrity });
}

export function buildRestorePlan(snapshot, verification) {
  requireValue(verification?.ok === true, 'RESTORE_VERIFICATION_REQUIRED', 409);
  return {
    schema: RESTORE_PLAN_SCHEMA,
    snapshot_id: snapshot.id,
    integritySha256: snapshot.integritySha256,
    dry_run_supported: true,
    automatic_activation: false,
    requires_owner_approval: true,
    steps: [
      { id: 'verify-integrity', destructive: false, status: 'VERIFIED' },
      { id: 'reconstruct-d1-logical-state', destructive: true, table_count: verification.database.tableCount, row_count: verification.database.rowCount },
      { id: 'verify-r2-inventory', destructive: false, object_count: verification.r2.objectCount, total_bytes: verification.r2.totalBytes },
      { id: 'restore-critical-code-from-independent-copy', destructive: true, external_proof_required: true },
      { id: 'activate-restored-runtime', destructive: true, owner_approval_required: true },
    ],
  };
}

export function createRestoreService(options = {}) {
  const { storage, target = null, audit = async () => {} } = options || {};
  if (!storage) {
    const legacyAdapters = Object.fromEntries(
      methods.filter(method => typeof options?.[method] === 'function').map(method => [method, options[method]])
    );
    return port('backup/restore-service', methods, legacyAdapters);
  }
  async function resolve(input = {}, context = {}) {
    requireValue(storage && typeof storage.get === 'function', 'RESTORE_STORAGE_GET_REQUIRED');
    const snapshot = input.snapshot || (input.id ? await storage.get(String(input.id), context) : null);
    if (!snapshot) throw new DomainError('SNAPSHOT_NOT_FOUND', 404);
    return snapshot;
  }

  return Object.freeze({
    async plan(input = {}, context = {}) {
      const snapshot = await resolve(input, context);
      const verification = await verifyRestoreCandidate(snapshot);
      if (!verification.ok) throw new DomainError(verification.code || 'RESTORE_VERIFICATION_FAILED', 409);
      const plan = buildRestorePlan(snapshot, verification);
      await audit({ kind: 'RESTORE_PLAN', snapshot_id: snapshot.id, ok: true, destructive: false });
      return { ok: true, verification, plan };
    },

    async verify(input = {}, context = {}) {
      const snapshot = await resolve(input, context);
      const verification = await verifyRestoreCandidate(snapshot);
      await audit({ kind: 'RESTORE_VERIFY', snapshot_id: snapshot.id, ok: verification.ok === true, code: verification.code || null, destructive: false });
      return verification;
    },

    async restore(input = {}, context = {}) {
      const snapshot = await resolve(input, context);
      const verification = await verifyRestoreCandidate(snapshot);
      if (!verification.ok) throw new DomainError(verification.code || 'RESTORE_VERIFICATION_FAILED', 409);

      requireValue(context?.owner === true, 'RESTORE_OWNER_REQUIRED', 403);
      requireValue(Array.isArray(context?.permissions) && context.permissions.includes('backup:restore'), 'RESTORE_PERMISSION_REQUIRED', 403);
      requireValue(input?.approval?.approved === true, 'RESTORE_EXPLICIT_APPROVAL_REQUIRED', 403);
      requireValue(input?.approval?.action === 'RESTORE_SYSTEM', 'RESTORE_APPROVAL_ACTION_INVALID', 403);
      requireValue(String(input?.approval?.snapshot_id || '') === String(snapshot.id || ''), 'RESTORE_APPROVAL_SNAPSHOT_MISMATCH', 403);
      requireValue(target && typeof target.restoreDatabase === 'function', 'RESTORE_TARGET_DATABASE_REQUIRED', 503);
      requireValue(typeof target.verifyCriticalCode === 'function', 'RESTORE_CRITICAL_CODE_VERIFIER_REQUIRED', 503);
      requireValue(typeof target.activate === 'function', 'RESTORE_TARGET_ACTIVATE_REQUIRED', 503);

      // The system snapshot intentionally stores an R2 inventory, not every R2
      // object byte. Critical executable code must therefore be proven from the
      // independent ShardVault/R2 code archive before any activation.
      const codeProof = await target.verifyCriticalCode({ snapshot, verification }, context);
      requireValue(codeProof?.ok === true, 'RESTORE_CRITICAL_CODE_PROOF_REQUIRED', 409);

      await target.restoreDatabase(snapshot.exports.database, context);
      const activation = await target.activate({ snapshot, verification, codeProof }, context);
      requireValue(activation?.ok === true, 'RESTORE_ACTIVATION_NOT_CONFIRMED', 503);

      const result = {
        ok: true,
        status: 'RESTORED',
        snapshot_id: snapshot.id,
        integritySha256: snapshot.integritySha256,
        production_activation_automatic: false,
        code_proof: { ok: true, source: codeProof.source || null },
      };
      await audit({ kind: 'RESTORE_EXECUTE', snapshot_id: snapshot.id, ok: true, destructive: true });
      return result;
    },
  });
}

import test from 'node:test';
import assert from 'node:assert/strict';

import { createVerifiedBackupService } from '../src/backup/backup-service.js';
import { createRestoreService, verifyRestoreCandidate, comparePatrimonyExports } from '../src/backup/restore-service.js';

function memoryStorage() {
  const rows = new Map();
  return {
    rows,
    async put(snapshot) { rows.set(snapshot.id, structuredClone(snapshot)); },
    async get(id) { return rows.has(id) ? structuredClone(rows.get(id)) : null; },
    async list() { return [...rows.values()]; },
  };
}

async function verifiedFixture() {
  const storage = memoryStorage();
  const backups = createVerifiedBackupService({
    storage,
    now: () => '2026-09-20T04:00:00.000Z',
    sources: {
      database: async () => ({
        type: 'MEL_D1_LOGICAL_EXPORT_V1',
        tableCount: 1,
        tables: [{ name: 'memories', schema: 'CREATE TABLE memories(id TEXT)', rowCount: 1, rows: [{ id: 'm1' }] }],
      }),
      r2_inventory: async () => ({
        type: 'MEL_R2_INVENTORY_V1',
        objectCount: 1,
        objects: [{ key: 'media/a', size: 12, etag: 'etag-a', uploaded: null }],
      }),
      runtime: async () => ({
        type: 'MEL_RUNTIME_DESCRIPTOR_V1',
        appVersion: '0.2.5',
        dbSchemaVersion: 7,
        worker: 'meliturgos',
        candidateBranch: 'candidate/mel-clean-autonomy',
        runtimeEnvironment: 'production',
      }),
    },
  });
  const created = await backups.create({ id: 'restore-proof' });
  return { storage, snapshot: storage.rows.get(created.id) };
}

test('restore candidate verifies complete D1, R2 inventory and runtime descriptor', async () => {
  const { snapshot } = await verifiedFixture();
  const result = await verifyRestoreCandidate(snapshot);
  assert.equal(result.ok, true);
  assert.equal(result.database.tableCount, 1);
  assert.equal(result.database.rowCount, 1);
  assert.equal(result.r2.objectCount, 1);
  assert.equal(result.critical_recovery_scope.production_activation_automatic, false);
  assert.equal(result.critical_recovery_scope.r2_object_bytes_embedded, false);
});

test('restore service produces a non-activating plan and fails closed without exact approval', async () => {
  const { storage, snapshot } = await verifiedFixture();
  const service = createRestoreService({ storage });
  const planned = await service.plan({ id: snapshot.id });
  assert.equal(planned.ok, true);
  assert.equal(planned.plan.automatic_activation, false);
  assert.equal(planned.plan.requires_owner_approval, true);
  await assert.rejects(
    () => service.restore({ id: snapshot.id }),
    (error) => error?.message === 'RESTORE_OWNER_REQUIRED',
  );
});

test('restore execution requires owner permission, exact snapshot approval and critical-code proof', async () => {
  const { storage, snapshot } = await verifiedFixture();
  const calls = [];
  const service = createRestoreService({
    storage,
    target: {
      async verifyCriticalCode() { calls.push('code'); return { ok: true, source: 'shardvault-7x' }; },
      async restoreDatabase(database) { calls.push(['db', database.tableCount]); },
      async activate() { calls.push('activate'); return { ok: true }; },
    },
  });
  const result = await service.restore({
    id: snapshot.id,
    approval: { approved: true, action: 'RESTORE_SYSTEM', snapshot_id: snapshot.id },
  }, {
    owner: true,
    permissions: ['backup:restore'],
  });
  assert.equal(result.ok, true);
  assert.equal(result.production_activation_automatic, false);
  assert.deepEqual(calls, ['code', ['db', 1], 'activate']);
});

test('tampered verified snapshot is rejected before restore planning', async () => {
  const { storage, snapshot } = await verifiedFixture();
  const tampered = structuredClone(snapshot);
  tampered.exports.database.tables[0].rows.push({ id: 'evil' });
  storage.rows.set(snapshot.id, tampered);
  const service = createRestoreService({ storage });
  await assert.rejects(
    () => service.plan({ id: snapshot.id }),
    /SNAPSHOT_ENTRY_INTEGRITY_MISMATCH|SNAPSHOT_INTEGRITY_MISMATCH/,
  );
});

test('patrimony comparison reads two exports and writes nothing', () => {
  const table = (name, ids) => ({
    name,
    schema: 'CREATE TABLE ' + name + '(' + (name === 'evolution_ledger' ? 'event_id' : 'id') + ' TEXT)',
    rowCount: ids.length,
    rows: ids.map(id => ({ [name === 'evolution_ledger' ? 'event_id' : 'id']: id })),
  });
  const pack = (ledger, conversations, jobs) => ({
    type: 'MEL_D1_LOGICAL_EXPORT_V1',
    tableCount: 3,
    tables: [table('evolution_ledger', ledger), table('conversations', conversations), table('dev_jobs', jobs)],
  });
  const before = pack(['e1'], ['c1'], ['j1']);
  const same = comparePatrimonyExports(before, pack(['e1'], ['c1'], ['j1']));
  assert.equal(same.ok, true);
  assert.equal(same.identical, true);
  assert.equal(same.production_written, false);
  const changed = comparePatrimonyExports(before, pack(['e1', 'e2'], ['c1'], ['j1']));
  assert.equal(changed.identical, false);
  assert.equal(changed.tables.evolution_ledger.same, false);
  assert.equal(changed.tables.conversations.same, true);
  assert.equal(changed.production_written, false);
});

test('the patrimony comparison is a real capability and writes nothing', async () => {
  const { createGen2Runtime } = await import('../src/core/orchestrator/gen2-runtime.js');
  const runtime = createGen2Runtime({ env: {} });
  const pack = (ids) => ({
    type: 'MEL_D1_LOGICAL_EXPORT_V1',
    tableCount: 3,
    tables: ['evolution_ledger', 'conversations', 'dev_jobs'].map(name => ({
      name,
      schema: 'CREATE TABLE ' + name + '(' + (name === 'evolution_ledger' ? 'event_id' : 'id') + ' TEXT)',
      rowCount: ids.length,
      rows: ids.map(id => ({ [name === 'evolution_ledger' ? 'event_id' : 'id']: id })),
    })),
  });
  const result = await runtime.bus.execute('backup.patrimony.compare', {
    before: pack(['a']),
    after: pack(['a', 'b']),
  }, { owner: 'owner', permissions: [] });
  assert.equal(result.ok, true);
  assert.equal(result.identical, false);
  assert.equal(result.production_written, false);
  assert.equal(result.tables.evolution_ledger.after, 2);
});

function patrimonyFixture() {
  return {
    type: 'MEL_D1_LOGICAL_EXPORT_V1',
    tableCount: 3,
    tables: [
      { name: 'evolution_ledger', schema: 'CREATE TABLE evolution_ledger(event_id TEXT UNIQUE, evidence_json TEXT)', rows: [
        { event_id: 'e1', evidence_json: '{"verified":true}' },
        { event_id: 'e2', evidence_json: '{"verified":false}' },
      ] },
      { name: 'conversations', schema: 'CREATE TABLE conversations(id TEXT PRIMARY KEY, title TEXT)', rows: [
        { id: 'c1', title: 'Conversation originale' },
      ] },
      { name: 'dev_jobs', schema: 'CREATE TABLE dev_jobs(id TEXT PRIMARY KEY, result_json TEXT)', rows: [
        { id: 'j1', result_json: '{"status":"WAITING_TEACHER"}' },
      ] },
    ].map(table => ({ ...table, rowCount: table.rows.length })),
  };
}

test('patrimony comparison rejects changed content even when every identity and row count is preserved', () => {
  const before = patrimonyFixture();
  for (const [name, field] of [['evolution_ledger', 'evidence_json'], ['conversations', 'title'], ['dev_jobs', 'result_json']]) {
    const after = structuredClone(before);
    after.tables.find(table => table.name === name).rows[0][field] = 'corrupted';
    const result = comparePatrimonyExports(before, after);
    assert.equal(result.ok, true);
    assert.equal(result.identical, false, name + ' content must be compared');
    assert.equal(result.tables[name].same, false);
    assert.equal(result.production_written, false);
  }
  assert.deepEqual(before, patrimonyFixture(), 'comparison must not mutate the source export');
});

test('patrimony comparison accepts the same complete data in a different table, row and property order', () => {
  const before = patrimonyFixture();
  const after = structuredClone(before);
  after.tables.reverse();
  for (const table of after.tables) {
    table.rows.reverse();
    table.rows = table.rows.map(row => Object.fromEntries(Object.entries(row).reverse()));
  }
  const result = comparePatrimonyExports(before, after);
  assert.equal(result.ok, true);
  assert.equal(result.identical, true);
  assert.equal(result.production_written, false);
});

test('patrimony comparison fails closed when a required table is absent, even from both exports', () => {
  for (const side of ['before', 'after', 'both']) {
    const before = patrimonyFixture();
    const after = patrimonyFixture();
    for (const pack of side === 'before' ? [before] : side === 'after' ? [after] : [before, after]) {
      pack.tables = pack.tables.filter(table => table.name !== 'dev_jobs');
      pack.tableCount = pack.tables.length;
    }
    const result = comparePatrimonyExports(before, after);
    assert.equal(result.ok, false);
    assert.equal(result.identical, false);
    assert.equal(result.code, 'RESTORE_PATRIMONY_TABLE_REQUIRED');
    assert.equal(result.side, side === 'both' ? 'before' : side);
    assert.equal(result.table, 'dev_jobs');
    assert.equal(result.production_written, false);
  }
});

test('patrimony comparison rejects duplicate tables and missing or duplicate row identities', () => {
  const cases = [
    {
      code: 'RESTORE_PATRIMONY_DUPLICATE_TABLE',
      mutate(pack) { pack.tables.push(structuredClone(pack.tables[0])); pack.tableCount += 1; },
    },
    {
      code: 'RESTORE_PATRIMONY_SCHEMA_REQUIRED',
      mutate(pack) { pack.tables[0].schema = null; },
    },
    {
      code: 'RESTORE_PATRIMONY_ROW_ID_REQUIRED',
      mutate(pack) { delete pack.tables[0].rows[0].event_id; },
    },
    {
      code: 'RESTORE_PATRIMONY_DUPLICATE_ROW_ID',
      mutate(pack) { pack.tables[0].rows[1].event_id = pack.tables[0].rows[0].event_id; },
    },
  ];
  for (const { code, mutate } of cases) {
    const pack = patrimonyFixture();
    mutate(pack);
    const result = comparePatrimonyExports(pack, structuredClone(pack));
    assert.equal(result.ok, false, code);
    assert.equal(result.identical, false);
    assert.equal(result.code, code);
    assert.equal(result.side, 'before');
    assert.equal(result.table, 'evolution_ledger');
    assert.equal(result.production_written, false);
  }
});

test('patrimony comparison detects lost columns or schema constraints without exposing row contents', () => {
  const before = patrimonyFixture();
  const after = structuredClone(before);
  after.tables[0].schema = 'CREATE TABLE evolution_ledger(event_id TEXT, evidence_json TEXT)';
  const result = comparePatrimonyExports(before, after);
  assert.equal(result.ok, true);
  assert.equal(result.identical, false);
  assert.equal(result.tables.evolution_ledger.same, false);
  assert.equal(JSON.stringify(result).includes('verified'), false);
});

test('patrimony guard compares real isolated SQLite exports and detects a corrupted restored row', async () => {
  const { sqliteD1 } = await import('./helpers/sqlite-d1.mjs');
  const { exportD1SystemState } = await import('../src/backup/system-backup-runtime.js');
  const source = sqliteD1();
  const restored = sqliteD1();
  try {
    const fixture = patrimonyFixture();
    for (const database of [source, restored]) {
      for (const table of fixture.tables) {
        await database.prepare(table.schema).run();
        for (const row of database === restored ? [...table.rows].reverse() : table.rows) {
          const columns = Object.keys(row);
          await database.prepare(
            `INSERT INTO ${table.name} (${columns.join(',')}) VALUES (${columns.map(() => '?').join(',')})`
          ).bind(...Object.values(row)).run();
        }
      }
    }
    const before = await exportD1SystemState(source, { pageSize: 1 });
    const after = await exportD1SystemState(restored, { pageSize: 1 });
    assert.equal(comparePatrimonyExports(before, after).identical, true);

    await restored.prepare('UPDATE dev_jobs SET result_json = ? WHERE id = ?').bind('lost evidence', 'j1').run();
    const corrupted = comparePatrimonyExports(before, await exportD1SystemState(restored));
    assert.equal(corrupted.ok, true);
    assert.equal(corrupted.identical, false);
    assert.equal(corrupted.tables.dev_jobs.same, false);
    assert.equal(corrupted.production_written, false);
    assert.deepEqual(await exportD1SystemState(source), before, 'the source database remains unchanged');
  } finally {
    source.close();
    restored.close();
  }
});

// MEL-FOUNDER-07: isolated restore of ledger, conversations and jobs, then
// counts and fingerprints; production is never a target.
test('an isolated copy restores ledger, conversations and jobs and matches counts and fingerprints', async () => {
  const { verifyIsolatedRestore } = await import('../src/backup/restore-service.js');
  const { sqliteD1 } = await import('./helpers/sqlite-d1.mjs');
  const { exportD1SystemState } = await import('../src/backup/system-backup-runtime.js');
  const fixture = patrimonyFixture();
  const source = sqliteD1();
  const writes = [];
  try {
    for (const table of fixture.tables) {
      await source.prepare(table.schema).run();
      for (const row of table.rows) {
        const columns = Object.keys(row);
        await source.prepare(`INSERT INTO ${table.name} (${columns.join(',')}) VALUES (${columns.map(() => '?').join(',')})`).bind(...Object.values(row)).run();
      }
    }
    const exported = await exportD1SystemState(source, { pageSize: 1 });
    const isolated = sqliteD1();
    try {
      const target = { isolated: true, async restore(data) {
        writes.push('isolated');
        for (const table of data.tables) {
          await isolated.prepare(table.schema).run();
          for (const row of table.rows) {
            const columns = Object.keys(row);
            await isolated.prepare(`INSERT INTO ${table.name} (${columns.join(',')}) VALUES (${columns.map(() => '?').join(',')})`).bind(...Object.values(row)).run();
          }
        }
        return exportD1SystemState(isolated);
      } };
      const result = await verifyIsolatedRestore(exported, target);
      assert.equal(result.ok, true);
      assert.equal(result.identical, true);
      assert.equal(result.isolated, true);
      assert.equal(result.production_written, false);
      for (const name of ['evolution_ledger', 'conversations', 'dev_jobs']) {
        assert.equal(result.tables[name].before, result.tables[name].after, name);
        assert.match(result.fingerprints[name].before, /^[0-9a-f]{64}$/);
        assert.equal(result.tables[name].fingerprint_match, true, name);
      }
    } finally { isolated.close(); }
    for (const target of [null, { restore: async () => { writes.push('production'); } }, { isolated: true, production: true, restore: async () => { writes.push('production'); } }]) {
      const refused = await verifyIsolatedRestore(exported, target);
      assert.equal(refused.code, 'RESTORE_ISOLATED_TARGET_REQUIRED');
      assert.equal(refused.production_written, false);
    }
    assert.deepEqual(writes, ['isolated'], 'no write ever targets a non-isolated database');
  } finally { source.close(); }
});
